run_visual_gates() {
  run_logged_gate \
    "Control UI browser screenshot gate" \
    "$CONTROL_LOG" \
    env \
      HEPTA_BROWSER_SMOKE_DIR="$CONTROL_OUT_DIR" \
      HEPTA_BROWSER_SMOKE_REPORT_PATH="$CONTROL_BROWSER_REPORT_PATH" \
      HEPTA_CONTROL_UI_SERVER_LOG="$OUT_DIR/control-ui-server.log" \
      ./scripts/hepta-control-ui-browser-smoke.sh

  if [[ ! -s "$CONTROL_BROWSER_REPORT_PATH" ]]; then
    echo "Control UI browser smoke report missing: ${CONTROL_BROWSER_REPORT_PATH}" >&2
    exit 1
  fi

  jq -e '
    .runtime == "hepta"
    and .status == "ready"
    and .control_ui_product_first_ready == true
    and .control_ui_telegram_shell_ready == true
    and .control_ui_top_design_referee_ready == true
    and .control_ui_320_reflow_ready == true
