run_native_packaging_gate() {
  run_logged_gate \
    "Native packaging metadata + local unsigned app bundle probe" \
    "$PACKAGING_LOG" \
    env \
      HEPTA_NATIVE_PACKAGING_GATE_REPORT_PATH="$PACKAGING_REPORT_PATH" \
      HEPTA_NATIVE_CARGO_TARGET_DIR="$NATIVE_WINDOW_CARGO_TARGET_DIR" \
      ./scripts/hepta-native-packaging-gate.sh

  if [[ ! -s "$PACKAGING_REPORT_PATH" ]]; then
    echo "Native packaging gate report missing: ${PACKAGING_REPORT_PATH}" >&2
    exit 1
  fi

  jq -e '
    .runtime == "hepta"
    and .status == "ready"
    and .local_packaging_gate_ready == true
    and .packaging_evidence_mode == "metadata_plus_local_unsigned_app_bundle_probe"
    and .local_unsigned_app_bundle_probe_ready == true
    and .local_unsigned_app_bundle.ready == true
    and .local_unsigned_app_bundle.info_plist_ready == true
    and .local_unsigned_app_bundle.icon_ready == true
    and .local_unsigned_app_bundle.mach_o_binary_ready == true
    and .local_unsigned_app_bundle.bundle_identifier == "ai.hepta.nativeapp"
    and .local_unsigned_app_bundle.bundle_executable == "hepta-native"
    and .local_unsigned_app_bundle.bundle_name == "Hepta Native"
    and .local_unsigned_app_bundle.distribution_signed == false
    and .local_unsigned_app_bundle.distribution_notarized == false
    and .local_unsigned_app_bundle.distribution_stapled == false
    and .local_unsigned_app_bundle.public_distribution_artifact_written == false
    and .runner.startup_timeout_sec >= 300
    and .hepta_native_release_packaging_ready == true
    and .reports_synchronized == true
    and .missing_route_count == 0
    and .side_effects.external_send_performed == false
    and .side_effects.provider_invoked == false
    and .side_effects.model_invoked == false
    and .side_effects.channel_send_performed == false
    and .side_effects.native_post_mutation_performed == false
    and .side_effects.gateway_mutation_performed == false
  ' "$PACKAGING_REPORT_PATH" >/dev/null

  native_packaging_gate_json="$(<"$PACKAGING_REPORT_PATH")"
}

run_native_distribution_preflight_gate() {
  run_logged_gate \
    "Native distribution preflight gate" \
    "$DISTRIBUTION_PREFLIGHT_LOG" \
    env \
      HEPTA_NATIVE_DISTRIBUTION_PREFLIGHT_REPORT_PATH="$DISTRIBUTION_PREFLIGHT_REPORT_PATH" \
      HEPTA_NATIVE_DISTRIBUTION_PREFLIGHT_PACKAGING_REPORT_PATH="$PACKAGING_REPORT_PATH" \
      ./scripts/hepta-native-distribution-preflight-gate.sh

  if [[ ! -s "$DISTRIBUTION_PREFLIGHT_REPORT_PATH" ]]; then
    echo "Native distribution preflight report missing: ${DISTRIBUTION_PREFLIGHT_REPORT_PATH}" >&2
    exit 1
  fi

  jq -e '
    .status == "ready"
    and .distribution_preflight_gate_ready == true
    and .distribution_preflight_mode == "static_distribution_workflow_plus_unsigned_bundle_probe"
    and .distribution_static_contract_ready == true
    and .unsigned_app_bundle_probe.ready == true
    and .unsigned_app_bundle_probe.app_bundle_exists == true
    and .unsigned_app_bundle_probe.codesign_status == "unsigned_expected"
    and .public_distribution_ready == false
    and .release_approval_required == true
    and .credential_values_read == false
    and .keychain_identity_lookup_performed == false
    and .network_call_performed == false
    and .notary_submission_performed == false
    and .public_distribution_artifact_written == false
    and .app_signed == false
    and .app_notarized == false
    and .app_stapled == false
    and (.blockers | index("operator_release_approval_required") != null)
    and (.blockers | index("public_distribution_artifact_not_written") != null)
    and .side_effects.credential_value_read == false
    and .side_effects.network_call_performed == false
    and .side_effects.notary_submission_performed == false
    and .side_effects.public_distribution_artifact_written == false
  ' "$DISTRIBUTION_PREFLIGHT_REPORT_PATH" >/dev/null

  native_distribution_preflight_json="$(<"$DISTRIBUTION_PREFLIGHT_REPORT_PATH")"
}

run_release_signing_capability_gate() {
  run_logged_gate \
    "UI release signing capability gate" \
    "$RELEASE_SIGNING_CAPABILITY_LOG" \
    env \
      HEPTA_UI_PRODUCT_READINESS_DIR="$OUT_DIR" \
      HEPTA_UI_RELEASE_SIGNING_CAPABILITY_REPORT_PATH="$RELEASE_SIGNING_CAPABILITY_REPORT_PATH" \
      HEPTA_UI_RELEASE_SIGNING_CAPABILITY_DIR="$RELEASE_SIGNING_CAPABILITY_DIR" \
      ./scripts/hepta-ui-release-signing-capability-gate.sh

  if [[ ! -s "$RELEASE_SIGNING_CAPABILITY_REPORT_PATH" ]]; then
    echo "UI release signing capability report missing: ${RELEASE_SIGNING_CAPABILITY_REPORT_PATH}" >&2
    exit 1
  fi

  jq -e '
    .status == "ready"
    and .release_signing_capability_gate_ready == true
    and .capability_kind == "local_release_signing_notary_prerequisite_audit"
    and .package_metadata.signing_identity_configured == true
    and .package_metadata.bundle_identifier == "ai.hepta.nativeapp"
    and .package_metadata.bundle_executable == "hepta-native"
    and .package_metadata.bundle_name == "Hepta Native"
    and .local_tooling.distribution_tools_ready == true
    and .release_script_capabilities.notary_keychain_profile_supported == true
    and .release_script_capabilities.release_artifact_receipt_output_supported == true
    and .release_script_capabilities.spctl_failure_is_hard_failure == true
    and (.release_execution_prerequisites.keychain_identity_ready | type) == "boolean"
    and (.release_execution_prerequisites.notary_keychain_profile_ready | type) == "boolean"
    and (.release_execution_prerequisites.notary_credentials_ready | type) == "boolean"
    and (.release_execution_prerequisites.release_signing_execution_prerequisites_ready | type) == "boolean"
    and (.notary_credentials.optional_keychain_profile_keychain_lookup_performed | type) == "boolean"
    and (.notary_credentials.optional_keychain_profile_keychain_item_found | type) == "boolean"
    and (.notary_credentials.optional_keychain_profile_lookup_output_sha256 | test("^[0-9a-f]{64}$"))
    and .notary_credentials.optional_keychain_profile_lookup_output_bytes > 0
    and .notary_credentials.optional_keychain_profile_lookup_raw_output_persisted == false
    and .claim_boundary.local_release_signing_capability_audit_ready == true
    and .claim_boundary.release_artifact_claim_ready == false
    and .claim_boundary.public_distribution_claim_ready == false
    and .claim_boundary.release_claim_ready == false
    and .claim_boundary.live_product_claim_ready == false
    and .side_effects.keychain_identity_lookup_performed == true
    and .side_effects.keychain_identity_lookup_raw_output_persisted == false
    and (.side_effects.notary_profile_keychain_lookup_performed | type) == "boolean"
    and .side_effects.notary_profile_keychain_lookup_raw_output_persisted == false
    and .side_effects.credential_value_captured == false
    and .side_effects.network_call_performed == false
    and .side_effects.notary_submission_performed == false
    and .side_effects.app_signed == false
    and .side_effects.app_notarized == false
    and .side_effects.app_stapled == false
    and .side_effects.public_distribution_artifact_written == false
    and .side_effects.external_mutation == false
  ' "$RELEASE_SIGNING_CAPABILITY_REPORT_PATH" >/dev/null

  release_signing_capability_json="$(<"$RELEASE_SIGNING_CAPABILITY_REPORT_PATH")"
}

native_window_smoke_requested() {
  case "$INCLUDE_NATIVE_WINDOW_SMOKE" in
    1 | true | TRUE | yes | YES | on | ON)
      return 0
      ;;
    *)
      return 1
      ;;
  esac
}

native_window_blocked_allowed() {
  case "$ALLOW_NATIVE_WINDOW_BLOCKED" in
    1 | true | TRUE | yes | YES | on | ON)
      return 0
      ;;
    *)
      return 1
      ;;
  esac
}

native_window_route_smoke_requested() {
  case "$INCLUDE_NATIVE_WINDOW_ROUTE_SMOKE" in
    1 | true | TRUE | yes | YES | on | ON)
      return 0
      ;;
    *)
      return 1
      ;;
  esac
}

native_window_secondary_smoke_requested() {
  case "$INCLUDE_NATIVE_WINDOW_SECONDARY_SMOKE" in
    1 | true | TRUE | yes | YES | on | ON)
      return 0
      ;;
    *)
      return 1
      ;;
  esac
}

native_window_secondary_mobile_smoke_requested() {
  case "$INCLUDE_NATIVE_WINDOW_SECONDARY_MOBILE_SMOKE" in
    1 | true | TRUE | yes | YES | on | ON)
      return 0
      ;;
    *)
      return 1
      ;;
  esac
}

truthy_flag() {
  case "${1:-}" in
    1 | true | TRUE | yes | YES | on | ON)
      return 0
      ;;
    *)
      return 1
      ;;
  esac
}

native_window_any_smoke_requested() {
  native_window_smoke_requested ||
    native_window_route_smoke_requested ||
    native_window_secondary_smoke_requested ||
    native_window_secondary_mobile_smoke_requested
}

native_window_shared_preflight_enabled() {
  truthy_flag "$NATIVE_WINDOW_SHARED_PREFLIGHT" && native_window_any_smoke_requested
}

cargo_with_native_window_target() {
  CARGO_TARGET_DIR="$NATIVE_WINDOW_CARGO_TARGET_DIR" cargo "$@"
}

run_native_window_shared_preflight_test() {
  local test_name="$1"
  if ! cargo_with_native_window_target test --manifest-path "$NATIVE_APP_MANIFEST" -q "$test_name" >&2; then
    echo "Hepta Native product readiness shared true-window preflight failed: $test_name" >&2
    exit 1
  fi
}

run_native_window_shared_preflight_and_prebuild() {
  if ! native_window_shared_preflight_enabled; then
    return
  fi

  run_native_window_shared_preflight_test current_codex_fixture_smoke_is_ready_without_live_side_effects
  run_native_window_shared_preflight_test hepta_fixture_cockpit_has_a_card_for_each_sample_event
  run_native_window_shared_preflight_test hepta_fixture_layout_policy_collapses_mobile_to_task_first_without_live_mutation
  NATIVE_WINDOW_SHARED_PREFLIGHT_READY=1

  if ! cargo_with_native_window_target build --manifest-path "$NATIVE_APP_MANIFEST" -q >&2; then
    echo "Hepta Native product readiness shared true-window prebuild failed" >&2
    exit 1
  fi
  NATIVE_WINDOW_SHARED_PREBUILD_READY=1
}

native_window_child_skip_preflight_flag() {
  if [[ "$NATIVE_WINDOW_SHARED_PREFLIGHT_READY" == "1" ]]; then
    printf '1'
  else
    printf '0'
  fi
}

native_window_child_prebuild_flag() {
  if [[ "$NATIVE_WINDOW_SHARED_PREBUILD_READY" == "1" ]]; then
    printf '0'
  else
    printf '1'
  fi
}

native_window_wrapper_preflight_flag() {
  if [[ "$NATIVE_WINDOW_SHARED_PREFLIGHT_READY" == "1" ]]; then
    printf '0'
  else
    printf '1'
  fi
}

native_window_wrapper_assume_preflight_flag() {
  if [[ "$NATIVE_WINDOW_SHARED_PREFLIGHT_READY" == "1" ]]; then
    printf '1'
  else
    printf '0'
  fi
}

native_window_wrapper_prebuild_flag() {
  if [[ "$NATIVE_WINDOW_SHARED_PREBUILD_READY" == "1" ]]; then
    printf '0'
  else
    printf '1'
  fi
}

run_optional_native_window_smoke() {
  if ! native_window_smoke_requested; then
    native_window_gate_json="$(
      jq -n \
        --arg output_dir "$NATIVE_WINDOW_OUT_DIR" \
        --arg report_path "$NATIVE_WINDOW_REPORT_PATH" \
        '{
          product:"Hepta Native",
          runtime:"hepta",
          enabled:false,
          optional_gate:true,
          status:"not_run",
          reason:"Set HEPTA_UI_PRODUCT_READINESS_INCLUDE_NATIVE_WINDOW_SMOKE=1 to collect true Makepad desktop/mobile window screenshots.",
          required_state:[
            "Unlocked macOS desktop",
            "Peekaboo Screen Recording permission",
            "Peekaboo Accessibility permission"
          ],
          output_dir:$output_dir,
          report_path:$report_path,
          true_window_capture_performed:false,
          fixture_cockpit_selected_ready:false,
          fixture_cockpit_selection_count:0,
          fixture_product_shell_selected_ready:false,
          fixture_product_shell_selection_count:0,
          fixture_matrix_composer_hidden_ready:false,
          fixture_matrix_composer_hidden_count:0,
          fixture_desktop_product_layout_ready:false,
          fixture_desktop_product_layout_count:0,
          fixture_mobile_task_first_layout_ready:false,
          fixture_mobile_task_first_layout_count:0,
          side_effects:{
            matrix_login:false,
            gateway_call:false,
            provider_invoked:false,
            channel_delivery:false,
            external_mutation:false
          }
        }'
    )"
    printf '%s\n' "$native_window_gate_json" >"$NATIVE_WINDOW_REPORT_PATH"
    : >"$NATIVE_WINDOW_LOG"
    return
  fi

  if ! env \
    HEPTA_NATIVE_WINDOW_SMOKE_DIR="$NATIVE_WINDOW_OUT_DIR" \
    HEPTA_NATIVE_WINDOW_SMOKE_CARGO_TARGET_DIR="$NATIVE_WINDOW_CARGO_TARGET_DIR" \
    HEPTA_NATIVE_WINDOW_SMOKE_STARTUP_TIMEOUT_SEC="$NATIVE_WINDOW_STARTUP_TIMEOUT_SEC" \
    HEPTA_NATIVE_WINDOW_SMOKE_PREBUILD="$(native_window_child_prebuild_flag)" \
    HEPTA_NATIVE_WINDOW_SMOKE_SKIP_PREFLIGHT="$(native_window_child_skip_preflight_flag)" \
    ./scripts/hepta-native-window-smoke.sh >"$NATIVE_WINDOW_REPORT_PATH" 2>"$NATIVE_WINDOW_LOG"; then
    if [[ -s "$NATIVE_WINDOW_REPORT_PATH" ]] && native_window_blocked_allowed; then
      local window_status
      window_status="$(jq -r '.status // ""' "$NATIVE_WINDOW_REPORT_PATH")"
      case "$window_status" in
        blocked_by_locked_screen | blocked_by_local_macos_permissions)
          native_window_gate_json="$(
            jq '. + {
              enabled:true,
              optional_gate:true,
              blocked_allowed:true,
              blocked_allowed_reason:"HEPTA_UI_PRODUCT_READINESS_ALLOW_NATIVE_WINDOW_BLOCKED records local macOS window-capture blockers without failing the combined artifact gate."
            }' "$NATIVE_WINDOW_REPORT_PATH"
          )"
          printf '%s\n' "$native_window_gate_json" >"$NATIVE_WINDOW_REPORT_PATH"
          return
          ;;
      esac
    fi
    echo "Native true Makepad window smoke failed; last log lines:" >&2
    tail -n 120 "$NATIVE_WINDOW_LOG" >&2 || true
    if [[ -s "$NATIVE_WINDOW_REPORT_PATH" ]]; then
      echo "Native true Makepad window smoke report:" >&2
      cat "$NATIVE_WINDOW_REPORT_PATH" >&2
    fi
    exit 1
  fi

  jq -e '
    .status == "ready"
    and .true_window_capture_performed == true
    and .fixture_cockpit_selected_ready == true
    and (.fixture_cockpit_selection_count >= 2)
    and .fixture_product_shell_selected_ready == true
    and (.fixture_product_shell_selection_count >= 2)
    and .fixture_matrix_composer_hidden_ready == true
    and (.fixture_matrix_composer_hidden_count >= 2)
    and .fixture_desktop_product_layout_ready == true
    and (.fixture_desktop_product_layout_count >= 1)
    and .fixture_mobile_task_first_layout_ready == true
    and (.fixture_mobile_task_first_layout_count >= 1)
    and .native_makepad_fixture_script_error_free == true
    and (.screenshots | length) == 2
    and (.screenshots | all(.visual_probe.ready == true))
    and .side_effects.external_mutation == false
  ' "$NATIVE_WINDOW_REPORT_PATH" >/dev/null

  native_window_gate_json="$(jq '. + {enabled:true, optional_gate:true}' "$NATIVE_WINDOW_REPORT_PATH")"
  printf '%s\n' "$native_window_gate_json" >"$NATIVE_WINDOW_REPORT_PATH"
}

