    HEPTA_NATIVE_WINDOW_ROUTE_SMOKE_PREBUILD="$(native_window_wrapper_prebuild_flag)" \
    ./scripts/hepta-native-window-route-smoke.sh >"$NATIVE_WINDOW_ROUTE_REPORT_PATH" 2>"$NATIVE_WINDOW_ROUTE_LOG"; then
