      route_window_status="$(jq -r '.status // ""' "$NATIVE_WINDOW_ROUTE_REPORT_PATH")"
      case "$route_window_status" in
        blocked_by_locked_screen | blocked_by_local_macos_permissions)
          native_window_route_gate_json="$(
            jq '. + {
              enabled:true,
              optional_gate:true,
              blocked_allowed:true,
              blocked_allowed_reason:"HEPTA_UI_PRODUCT_READINESS_ALLOW_NATIVE_WINDOW_BLOCKED records local macOS window-capture blockers without failing the combined route artifact gate."
            }' "$NATIVE_WINDOW_ROUTE_REPORT_PATH"
          )"
          printf '%s\n' "$native_window_route_gate_json" >"$NATIVE_WINDOW_ROUTE_REPORT_PATH"
          return
          ;;
      esac
    fi
    echo "Native true Makepad route window smoke failed; last log lines:" >&2
    tail -n 160 "$NATIVE_WINDOW_ROUTE_LOG" >&2 || true
    if [[ -s "$NATIVE_WINDOW_ROUTE_REPORT_PATH" ]]; then
      echo "Native true Makepad route window smoke report:" >&2
      cat "$NATIVE_WINDOW_ROUTE_REPORT_PATH" >&2
    fi
    exit 1
  fi

  jq -e '
    .status == "ready"
    and .true_window_capture_performed == true
    and .native_makepad_route_variants_ready == true
    and .route_top_design_referee_ready == true
    and .route_content_probe_ready == true
    and .route_count == 4
    and .route_screenshot_unique_count == 4
    and .route_screenshot_unique_ready == true
    and .screenshot_count == 4
    and (.routes | length) == 4
    and (.screenshots | length) == 4
    and (.screenshots | all(.visual_probe.ready == true))
    and (.screenshots | all(.visual_probe.route_content_ready == true))
    and .native_app_log_error_free == true
    and .side_effects.external_mutation == false
  ' "$NATIVE_WINDOW_ROUTE_REPORT_PATH" >/dev/null

  native_window_route_gate_json="$(jq '. + {enabled:true, optional_gate:true}' "$NATIVE_WINDOW_ROUTE_REPORT_PATH")"
  printf '%s\n' "$native_window_route_gate_json" >"$NATIVE_WINDOW_ROUTE_REPORT_PATH"
}

