          optional_gate:true,
          status:"not_run",
          reason:"Set HEPTA_UI_PRODUCT_READINESS_INCLUDE_NATIVE_WINDOW_SECONDARY_MOBILE_SMOKE=1 to collect mobile secondary-surface true-window screenshots.",
          required_state:[
            "Unlocked macOS desktop",
            "Peekaboo Screen Recording permission",
            "Peekaboo Accessibility permission"
          ],
          output_dir:$output_dir,
          report_path:$report_path,
          true_window_capture_performed:false,
          native_makepad_secondary_mobile_surfaces_ready:false,
          mobile_secondary_content_probe_ready:false,
          mobile_secondary_content_visible_count:0,
          surface_count:0,
          surface_screenshot_unique_count:0,
          surface_screenshot_unique_ready:false,
          screenshot_count:0,
          surfaces:[],
          screenshots:[],
          side_effects:{
            matrix_login:false,
            gateway_call:false,
            provider_invoked:false,
            channel_delivery:false,
            external_mutation:false
          }
        }'
    )"
    printf '%s\n' "$native_window_secondary_mobile_gate_json" >"$NATIVE_WINDOW_SECONDARY_MOBILE_REPORT_PATH"
    : >"$NATIVE_WINDOW_SECONDARY_MOBILE_LOG"
    return
  fi

  if ! env \
    HEPTA_NATIVE_WINDOW_SECONDARY_MOBILE_SMOKE_DIR="$NATIVE_WINDOW_SECONDARY_MOBILE_OUT_DIR" \
    HEPTA_NATIVE_WINDOW_SECONDARY_MOBILE_SMOKE_REPORT_PATH="$NATIVE_WINDOW_SECONDARY_MOBILE_REPORT_PATH" \
    HEPTA_NATIVE_WINDOW_SMOKE_CARGO_TARGET_DIR="$NATIVE_WINDOW_CARGO_TARGET_DIR" \
    HEPTA_NATIVE_WINDOW_SECONDARY_MOBILE_SMOKE_STARTUP_TIMEOUT_SEC="$NATIVE_WINDOW_STARTUP_TIMEOUT_SEC" \
    HEPTA_NATIVE_WINDOW_SECONDARY_MOBILE_SMOKE_ALLOW_BLOCKED="$ALLOW_NATIVE_WINDOW_BLOCKED" \
    HEPTA_NATIVE_WINDOW_SECONDARY_MOBILE_SMOKE_PREFLIGHT="$(native_window_wrapper_preflight_flag)" \
    HEPTA_NATIVE_WINDOW_SECONDARY_MOBILE_SMOKE_ASSUME_PREFLIGHT_READY="$(native_window_wrapper_assume_preflight_flag)" \
    HEPTA_NATIVE_WINDOW_SECONDARY_MOBILE_SMOKE_PREBUILD="$(native_window_wrapper_prebuild_flag)" \
    ./scripts/hepta-native-window-secondary-mobile-smoke.sh >"$NATIVE_WINDOW_SECONDARY_MOBILE_REPORT_PATH" 2>"$NATIVE_WINDOW_SECONDARY_MOBILE_LOG"; then
    if [[ -s "$NATIVE_WINDOW_SECONDARY_MOBILE_REPORT_PATH" ]] && native_window_blocked_allowed; then
      local secondary_mobile_window_status
      secondary_mobile_window_status="$(jq -r '.status // ""' "$NATIVE_WINDOW_SECONDARY_MOBILE_REPORT_PATH")"
      case "$secondary_mobile_window_status" in
        blocked_by_locked_screen | blocked_by_local_macos_permissions)
          native_window_secondary_mobile_gate_json="$(
            jq '. + {
              enabled:true,
              optional_gate:true,
              blocked_allowed:true,
              blocked_allowed_reason:"HEPTA_UI_PRODUCT_READINESS_ALLOW_NATIVE_WINDOW_BLOCKED records local macOS window-capture blockers without failing the combined mobile secondary-surface artifact gate."
            }' "$NATIVE_WINDOW_SECONDARY_MOBILE_REPORT_PATH"
          )"
          printf '%s\n' "$native_window_secondary_mobile_gate_json" >"$NATIVE_WINDOW_SECONDARY_MOBILE_REPORT_PATH"
          return
          ;;
      esac
    fi
    echo "Native true Makepad secondary mobile window smoke failed; last log lines:" >&2
    tail -n 160 "$NATIVE_WINDOW_SECONDARY_MOBILE_LOG" >&2 || true
    if [[ -s "$NATIVE_WINDOW_SECONDARY_MOBILE_REPORT_PATH" ]]; then
      echo "Native true Makepad secondary mobile window smoke report:" >&2
      cat "$NATIVE_WINDOW_SECONDARY_MOBILE_REPORT_PATH" >&2
    fi
    exit 1
  fi

  jq -e '
    .status == "ready"
    and .true_window_capture_performed == true
    and .native_makepad_secondary_mobile_surfaces_ready == true
    and .mobile_secondary_content_probe_ready == true
    and .mobile_secondary_content_visible_count >= 5
    and .surface_count == 5
    and .surface_screenshot_unique_count == 5
    and .surface_screenshot_unique_ready == true
    and .screenshot_count == 5
    and (.surfaces | length) == 5
    and (.screenshots | length) == 5
    and (.screenshots | all(.visual_probe.ready == true))
    and (.screenshots | all(.visual_probe.mobile_secondary_content_ready == true))
    and .native_app_log_error_free == true
    and .side_effects.external_mutation == false
  ' "$NATIVE_WINDOW_SECONDARY_MOBILE_REPORT_PATH" >/dev/null

  native_window_secondary_mobile_gate_json="$(jq '. + {enabled:true, optional_gate:true}' "$NATIVE_WINDOW_SECONDARY_MOBILE_REPORT_PATH")"
  printf '%s\n' "$native_window_secondary_mobile_gate_json" >"$NATIVE_WINDOW_SECONDARY_MOBILE_REPORT_PATH"
}

count_visual_artifacts() {
  control_screenshot_count=0
  local screenshot_name
  for screenshot_name in desktop narrow mobile phone320; do
    if [[ ! -s "$CONTROL_OUT_DIR/${screenshot_name}.png" ]]; then
      echo "Control UI browser gate did not produce ${screenshot_name}.png" >&2
      exit 1
    fi
    control_screenshot_count=$((control_screenshot_count + 1))
  done

  native_screenshot_count="$(find "$NATIVE_OUT_DIR" -maxdepth 1 -name '*.png' | wc -l | tr -d ' ')"

  if [[ "$control_screenshot_count" -lt 4 ]]; then
    echo "Control UI browser gate produced too few screenshots: ${control_screenshot_count}" >&2
    exit 1
  fi

  if [[ "$native_screenshot_count" -lt 40 ]]; then
    echo "Native fixture visual gate produced too few screenshots: ${native_screenshot_count}" >&2
    exit 1
  fi

  if [[ ! -s "$SELECTED_ROW_MANIFEST" ]]; then
    echo "Native fixture selected-row screenshot manifest missing: ${SELECTED_ROW_MANIFEST}" >&2
    exit 1
  fi

  selected_row_variant_count="$(jq 'length' "$SELECTED_ROW_MANIFEST")"
  if [[ "$selected_row_variant_count" -lt 18 ]]; then
    echo "Native fixture selected-row screenshot manifest is incomplete: ${selected_row_variant_count}" >&2
    exit 1
  fi
}

screenshot_artifact_json() {
  local surface="$1"
  local name="$2"
  local viewport="$3"
  local path="$4"

  if [[ ! -s "$path" ]]; then
    echo "UI product readiness screenshot missing: ${path}" >&2
    exit 1
  fi

  local bytes
  bytes="$(wc -c <"$path" | tr -d ' ')"
  if [[ "$bytes" -lt "$MIN_SCREENSHOT_BYTES" ]]; then
    echo "UI product readiness screenshot is suspiciously small: ${path} (${bytes} bytes)" >&2
    exit 1
  fi

  local sha
  sha="$(shasum -a 256 "$path" | awk '{print $1}')"

  jq -n \
    --arg surface "$surface" \
    --arg name "$name" \
    --arg viewport "$viewport" \
    --arg path "$path" \
    --arg sha "$sha" \
    --argjson bytes "$bytes" \
    '{
      surface:$surface,
      name:$name,
      viewport:$viewport,
      path:$path,
      bytes:$bytes,
      sha256:$sha
    }'
}

build_key_screenshots_json() {
  local screenshots_json="[]"
  local spec surface name viewport path artifact_json
  for spec in "${KEY_SCREENSHOTS[@]}"; do
    IFS='|' read -r surface name viewport path <<<"$spec"
    artifact_json="$(screenshot_artifact_json "$surface" "$name" "$viewport" "$path")"
    screenshots_json="$(jq -n --argjson list "$screenshots_json" --argjson item "$artifact_json" '$list + [$item]')"
  done
  printf '%s\n' "$screenshots_json"
}

write_screenshot_manifest() {
  local key_screenshots_json="$1"
  key_screenshot_count="$(jq 'length' <<<"$key_screenshots_json")"

  screenshot_manifest_json="$(
    jq -n \
      --arg product "Hepta UI" \
      --arg output_dir "$OUT_DIR" \
      --arg control_output_dir "$CONTROL_OUT_DIR" \
      --arg native_output_dir "$NATIVE_OUT_DIR" \
      --arg native_fixture_report_path "$NATIVE_FIXTURE_REPORT_PATH" \
      --arg selected_row_variant_manifest_path "$SELECTED_ROW_MANIFEST" \
      --argjson min_screenshot_bytes "$MIN_SCREENSHOT_BYTES" \
      --argjson control_screenshot_count "$control_screenshot_count" \
      --argjson native_screenshot_count "$native_screenshot_count" \
      --argjson key_screenshot_count "$key_screenshot_count" \
      --argjson selected_row_variant_count "$selected_row_variant_count" \
      --argjson native_fixture "$native_fixture_gate_json" \
      --argjson native_window "$native_window_gate_json" \
      --argjson native_window_route "$native_window_route_gate_json" \
      --argjson native_window_secondary "$native_window_secondary_gate_json" \
      --argjson native_window_secondary_mobile "$native_window_secondary_mobile_gate_json" \
      --argjson key_screenshots "$key_screenshots_json" \
      '{
        product:$product,
        output_dir:$output_dir,
        screenshot_manifest_ready:true,
        min_screenshot_bytes:$min_screenshot_bytes,
        screenshot_count:{
          control_ui:$control_screenshot_count,
          native:$native_screenshot_count,
          native_true_window:(($native_window.screenshots // []) | length),
          native_true_window_route:(($native_window_route.screenshots // []) | length),
          native_true_window_secondary:(($native_window_secondary.screenshots // []) | length),
          native_true_window_secondary_mobile:(($native_window_secondary_mobile.screenshots // []) | length),
          total:(
            $control_screenshot_count
            + $native_screenshot_count
            + (($native_window.screenshots // []) | length)
            + (($native_window_route.screenshots // []) | length)
            + (($native_window_secondary.screenshots // []) | length)
            + (($native_window_secondary_mobile.screenshots // []) | length)
          )
        },
        key_screenshot_count:$key_screenshot_count,
        key_screenshots:$key_screenshots,
        control_ui:{
          output_dir:$control_output_dir,
          expected_viewports:["1365x900","768x900","500x844","320x844"]
        },
        native:{
          output_dir:$native_output_dir,
          expected_viewports:["1280x800","500x844"],
          fixture_report_path:$native_fixture_report_path,
          selected_row_variant_manifest_path:$selected_row_variant_manifest_path,
          selected_row_variant_count:$selected_row_variant_count,
          selected_row_unique_count:$native_fixture.selected_row_unique_count,
          route_variant_unique_count:$native_fixture.route_variant_unique_count,
          mobile_route_variant_unique_count:$native_fixture.mobile_route_variant_unique_count,
          tempered_glass_visual_contract_ready:$native_fixture.native_tempered_glass_visual_contract_ready,
          tempered_glass_visual_contract:$native_fixture.tempered_glass_visual_contract,
          readability_contrast_clip_ready:$native_fixture.native_readability_contrast_clip_ready,
          header_icon_affordance_ready:$native_fixture.native_telegram_header_icon_affordance_ready,
          secondary_product_surfaces_ready:$native_fixture.native_secondary_product_surfaces_ready,
          secondary_product_surfaces:$native_fixture.secondary_product_surfaces,
          product_first_visible_copy_ready:$native_fixture.native_product_first_visible_copy_ready,
          visible_audit_chrome_absent:$native_fixture.native_visible_audit_chrome_absent,
          visible_audit_failure_count:$native_fixture.native_visible_audit_failure_count,
          true_window_smoke_enabled:($native_window.enabled == true),
          true_window_smoke_status:($native_window.status // "not_run"),
          true_window_smoke_ready:(
            ($native_window.enabled == true)
            and $native_window.status == "ready"
            and $native_window.true_window_capture_performed == true
            and (($native_window.screenshots // []) | length) == 2
            and ($native_window.screenshots | all(.visual_probe.ready == true))
          ),
          true_window_screenshot_count:(($native_window.screenshots // []) | length),
          true_window_screenshots:($native_window.screenshots // []),
          true_window_route_smoke_enabled:($native_window_route.enabled == true),
          true_window_route_smoke_status:($native_window_route.status // "not_run"),
          true_window_route_smoke_ready:(
            ($native_window_route.enabled == true)
            and $native_window_route.status == "ready"
            and $native_window_route.native_makepad_route_variants_ready == true
            and $native_window_route.route_top_design_referee_ready == true
            and $native_window_route.route_content_probe_ready == true
            and $native_window_route.route_screenshot_unique_count == 4
            and $native_window_route.route_screenshot_unique_ready == true
            and $native_window_route.screenshot_count == 4
            and ($native_window_route.screenshots | all(.visual_probe.ready == true))
            and ($native_window_route.screenshots | all(.visual_probe.route_content_ready == true))
          ),
          true_window_route_screenshot_count:(($native_window_route.screenshots // []) | length),
          true_window_route_screenshot_unique_count:($native_window_route.route_screenshot_unique_count // 0),
          true_window_route_screenshot_unique_ready:($native_window_route.route_screenshot_unique_ready // false),
          true_window_route_top_design_referee_ready:($native_window_route.route_top_design_referee_ready // false),
          true_window_route_content_probe_ready:($native_window_route.route_content_probe_ready // false),
          true_window_route_screenshots:($native_window_route.screenshots // []),
          true_window_secondary_smoke_enabled:($native_window_secondary.enabled == true),
          true_window_secondary_smoke_status:($native_window_secondary.status // "not_run"),
          true_window_secondary_smoke_ready:(
            ($native_window_secondary.enabled == true)
            and $native_window_secondary.status == "ready"
            and $native_window_secondary.native_makepad_secondary_surfaces_ready == true
            and $native_window_secondary.surface_count == 5
            and $native_window_secondary.surface_screenshot_unique_count == 5
            and $native_window_secondary.surface_screenshot_unique_ready == true
            and $native_window_secondary.screenshot_count == 5
            and ($native_window_secondary.screenshots | all(.visual_probe.ready == true))
          ),
          true_window_secondary_screenshot_count:(($native_window_secondary.screenshots // []) | length),
          true_window_secondary_screenshot_unique_count:($native_window_secondary.surface_screenshot_unique_count // 0),
          true_window_secondary_screenshot_unique_ready:($native_window_secondary.surface_screenshot_unique_ready // false),
          true_window_secondary_screenshots:($native_window_secondary.screenshots // []),
          true_window_secondary_mobile_smoke_enabled:($native_window_secondary_mobile.enabled == true),
          true_window_secondary_mobile_smoke_status:($native_window_secondary_mobile.status // "not_run"),
          true_window_secondary_mobile_smoke_ready:(
            ($native_window_secondary_mobile.enabled == true)
            and $native_window_secondary_mobile.status == "ready"
            and $native_window_secondary_mobile.native_makepad_secondary_mobile_surfaces_ready == true
            and $native_window_secondary_mobile.mobile_secondary_content_probe_ready == true
            and $native_window_secondary_mobile.mobile_secondary_content_visible_count >= 5
            and $native_window_secondary_mobile.surface_count == 5
            and $native_window_secondary_mobile.surface_screenshot_unique_count == 5
            and $native_window_secondary_mobile.surface_screenshot_unique_ready == true
            and $native_window_secondary_mobile.screenshot_count == 5
            and ($native_window_secondary_mobile.screenshots | all(.visual_probe.ready == true))
            and ($native_window_secondary_mobile.screenshots | all(.visual_probe.mobile_secondary_content_ready == true))
          ),
          true_window_secondary_mobile_content_probe_ready:($native_window_secondary_mobile.mobile_secondary_content_probe_ready // false),
          true_window_secondary_mobile_content_visible_count:($native_window_secondary_mobile.mobile_secondary_content_visible_count // 0),
          true_window_secondary_mobile_screenshot_count:(($native_window_secondary_mobile.screenshots // []) | length),
          true_window_secondary_mobile_screenshot_unique_count:($native_window_secondary_mobile.surface_screenshot_unique_count // 0),
          true_window_secondary_mobile_screenshot_unique_ready:($native_window_secondary_mobile.surface_screenshot_unique_ready // false),
          true_window_secondary_mobile_screenshots:($native_window_secondary_mobile.screenshots // [])
        }
      }'
  )"
  printf '%s\n' "$screenshot_manifest_json" >"$MANIFEST_PATH"
}

