          {
            gap_id:"mention_picker_send",
            current_path:"cached suggestions + live completed-token pill tray removal + live SendMessage/add_mentions payload wiring + live attachment caption AttachmentConfig.mentions wiring + live read-only Matrix user-directory search metadata + live bounded directory result promotion + local hover-card snapshot + local rich mention packet snapshot + payload scope controls + payload drilldown packet + typed mention contract packet + remote hover/profile/disambiguation/edit-reply result taxonomy packet",
            remaining_gap:"rich picker result promotion, richer directory result UI beyond bounded user-id token promotion, rich attachment editors, typed edit/reply payload scopes, remote disambiguation UI, remote hover-card/profile adapter",
            next_ui_safe_step:"coordinate backend mention contracts plus richer UI promotion contracts before wiring rich picker, remote disambiguation, remote hover-card/profile adapters, rich attachment editors, or edit/reply payload rewrites",
            status:"ui_drilldown_ready"
          },
          {
            gap_id:"voice_message_send",
            current_path:"live desktop audio SendAttachment/use_send_queue wiring + confirmed failed-handoff Retry + audio file handoff + selected-audio duration/codec/bounded WAV waveform analysis + review Play opener + real Drop pending-audio cleanup + recorder status/capture lifecycle + local capture/request snapshot + recorder lifecycle drilldown packet + typed recorder/upload contract packet + permission/capture/upload result taxonomy packet + mobile picker/review playback/drop cleanup/preflight controls",
            remaining_gap:"microphone permission, recorder/audio session, recorder waveform capture, codec/transcription, inline review player/scrubber, captured audio upload queue",
            next_ui_safe_step:"coordinate backend recorder/upload contracts before wiring microphone permission, recorder session, capture, recorder waveform, codec/transcription, inline review player, mobile picker, or captured upload work",
            status:"ui_drilldown_ready"
          }
        ] | map(. + {
          id:.gap_id,
          evidence_layers:[
            "hepta_telegram_base_contract",
            "native_fixture_dom_and_json",
            "combined_readiness_artifact",
            "handoff_report"
          ],
          acceptance_criteria:[
            ("Current UI evidence covers: " + .current_path),
            ("Implementation gap remains explicit: " + .remaining_gap),
            ("Next implementation acceptance requires: " + .next_ui_safe_step)
          ],
          acceptance_state:{
            current_ui_evidence:"machine_checked",
            implementation_gap:"explicit",
            side_effect_boundary:"locked",
            verification_gate:"scripts/hepta-ui-product-readiness-gate.sh"
          },
          side_effects:base_gap_side_effects
        })),
        side_effects:base_gap_side_effects
      }'
  )"

  printf '%s\n' "$base_gap_drilldown_json" >"$BASE_GAP_DRILLDOWN_PATH"

  jq -e '
    .schema_version == 2
    and .native_base_gap_drilldown_ready == true
    and .acceptance_matrix_ready == true
    and .side_effect_profile == "ui-local-readiness-only"
    and .gap_count == 12
    and (.gaps | length) == 12
    and ([.gaps[].gap_id] | sort) == ([
      "account_avatar_upload",
      "account_management",
      "file_upload_send",
      "matrix_link_resolution",
      "media_download_playback",
      "mention_picker_send",
      "message_edit_history",
      "message_report_send",
      "message_search",
      "notifications",
      "room_settings",
      "voice_message_send"
    ] | sort)
    and ([.gaps[].id] | sort) == ([.gaps[].gap_id] | sort)
    and (.gaps | all(.status == "ui_drilldown_ready"))
    and (.gaps | all((.current_path | length) > 0 and (.remaining_gap | length) > 0 and (.next_ui_safe_step | length) > 0))
    and (.gaps | all((.evidence_layers | length) >= 4))
    and (.gaps | all((.acceptance_criteria | length) >= 3))
    and (.gaps | all(.acceptance_state.current_ui_evidence == "machine_checked"))
    and (.gaps | all(.acceptance_state.implementation_gap == "explicit"))
    and (.gaps | all(.acceptance_state.side_effect_boundary == "locked"))
    and (.gaps | all(.side_effects.matrix_login == false))
    and (.gaps | all(.side_effects.gateway_call == false))
    and (.gaps | all(.side_effects.provider_invoked == false))
    and (.gaps | all(.side_effects.channel_delivery == false))
    and (.gaps | all(.side_effects.external_mutation == false))
    and (.gaps | all(.side_effects.matrix_request_submitted == false))
    and (.gaps | all(.side_effects.room_state_mutation == false))
    and (.gaps | all(.side_effects.membership_mutation == false))
    and (.gaps | all(.side_effects.account_profile_mutation == false))
    and .side_effects.matrix_login == false
    and .side_effects.gateway_call == false
    and .side_effects.provider_invoked == false
    and .side_effects.channel_delivery == false
    and .side_effects.external_mutation == false
    and .side_effects.matrix_request_submitted == false
    and .side_effects.room_state_mutation == false
    and .side_effects.membership_mutation == false
    and .side_effects.account_profile_mutation == false
  ' "$BASE_GAP_DRILLDOWN_PATH" >/dev/null
}

write_base_gap_work_queue() {
  base_gap_work_queue_json="$(
    jq -n \
      --arg product "Hepta Native" \
      --arg output_dir "$OUT_DIR" \
      --arg drilldown_path "$BASE_GAP_DRILLDOWN_PATH" \
      --argjson drilldown "$base_gap_drilldown_json" \
      '
      def priority_for($id): ({
        "message_search":1,
        "file_upload_send":2,
        "media_download_playback":3,
        "notifications":4,
        "room_settings":5,
        "matrix_link_resolution":6,
        "message_report_send":7,
        "message_edit_history":8,
        "mention_picker_send":9,
        "voice_message_send":10,
        "account_avatar_upload":11,
        "account_management":12
      }[$id]);
      def priority_reason_for($id): ({
        "message_search":"highest daily chat utility and read-only server-search bridge",
        "file_upload_send":"core composer payload path and visible queue recovery value",
        "media_download_playback":"core timeline consumption path with clear playback/decrypt boundary",
        "notifications":"room attention model affects repeat use and has confirmation-gated writes",
        "room_settings":"high-trust room metadata path with multiple confirmed mutation fields",
        "matrix_link_resolution":"navigation reliability path with server-context dependency",
        "message_report_send":"moderation workflow path after confirmed report_content boundary",
        "message_edit_history":"trust/audit path after typed full-history result contract evidence",
        "mention_picker_send":"composer quality path after text and attachment-caption mention handoff evidence",
        "voice_message_send":"mobile parity path gated by platform recorder permissions",
        "account_avatar_upload":"profile polish path gated by crop/camera/editor work",
        "account_management":"account/session path with the widest backend/security dependency"
      }[$id]);
      def touchpoints_for($id):
        if ($id == "mention_picker_send") then
          [
            "apps/hepta-native/src/shared/mentionable_text_input.rs",
            "apps/hepta-native/src/room/room_input_bar.rs",
            "apps/hepta-native/src/home/hepta_telegram_base_contract.rs",
            "scripts/hepta-native-fixture-visual-smoke.sh",
            "scripts/hepta-ui-product-readiness-gate.sh"
          ]
        elif ($id == "file_upload_send" or $id == "voice_message_send") then
          [
            "apps/hepta-native/src/room/room_input_bar.rs",
            "apps/hepta-native/src/home/hepta_telegram_base_contract.rs",
            "scripts/hepta-native-fixture-visual-smoke.sh",
            "scripts/hepta-ui-product-readiness-gate.sh"
          ]
        elif ($id == "account_avatar_upload" or $id == "account_management") then
          [
            "apps/hepta-native/src/settings/account_settings.rs",
            "apps/hepta-native/src/home/hepta_telegram_base_contract.rs",
            "scripts/hepta-native-fixture-visual-smoke.sh",
            "scripts/hepta-ui-product-readiness-gate.sh"
          ]
        else
          [
            "apps/hepta-native/src/home/room_screen.rs",
            "apps/hepta-native/src/home/hepta_telegram_base_contract.rs",
            "scripts/hepta-native-fixture-visual-smoke.sh",
            "scripts/hepta-ui-product-readiness-gate.sh"
          ]
        end;
      {
        product:$product,
        output_dir:$output_dir,
        schema_version:2,
        native_base_gap_work_queue_ready:true,
        source_drilldown_path:$drilldown_path,
        source_drilldown_schema:$drilldown.schema_version,
        item_count:($drilldown.gaps | length),
        ordering:"post_ui_contract_backend_dependency",
        items:(
          $drilldown.gaps
          | map({
              id:.id,
              gap_id:.gap_id,
              priority:priority_for(.id),
              priority_reason:priority_reason_for(.id),
              status:"ui_contract_ready",
              ui_lane_state:"complete",
              next_owner_lane:"backend_contract",
              current_ui_evidence:.current_path,
              remaining_gap:.remaining_gap,
              backend_contract_next_slice:.next_ui_safe_step,
              acceptance_criteria:.acceptance_criteria,
              acceptance_state:.acceptance_state,
              likely_touchpoints:touchpoints_for(.id),
              verification_gates:[
                "focused hepta_telegram_base_ contract test when Rust UI files change",
                "scripts/hepta-native-fixture-visual-smoke.sh",
                "scripts/hepta-ui-product-readiness-gate.sh"
              ],
              promotion_blocker:"live Matrix/backend/runtime implementation remains outside hepta-ui lane until backend contract adapters are coordinated",
              side_effects:.side_effects
            })
          | sort_by(.priority)
        ),
        side_effects:$drilldown.side_effects
      }'
  )"

  printf '%s\n' "$base_gap_work_queue_json" >"$BASE_GAP_WORK_QUEUE_PATH"

  jq -e \
    --arg drilldown_path "$BASE_GAP_DRILLDOWN_PATH" \
    '
      .schema_version == 2
      and .native_base_gap_work_queue_ready == true
      and .source_drilldown_path == $drilldown_path
      and .source_drilldown_schema == 2
      and .item_count == 12
      and (.items | length) == 12
      and ([.items[].priority] | sort) == [range(1;13)]
      and ([.items[].id] | sort) == ([
        "account_avatar_upload",
        "account_management",
        "file_upload_send",
        "matrix_link_resolution",
        "media_download_playback",
        "mention_picker_send",
        "message_edit_history",
        "message_report_send",
        "message_search",
        "notifications",
        "room_settings",
        "voice_message_send"
      ] | sort)
      and (.items | all(.status == "ui_contract_ready"))
      and (.items | all(.ui_lane_state == "complete"))
      and (.items | all(.next_owner_lane == "backend_contract"))
      and (.items | all((.backend_contract_next_slice | length) > 0))
      and (.items | all((.acceptance_criteria | length) >= 3))
      and (.items | all((.likely_touchpoints | length) >= 4))
      and (.items | all((.verification_gates | index("scripts/hepta-ui-product-readiness-gate.sh")) != null))
      and (.items | all(.acceptance_state.side_effect_boundary == "locked"))
      and (.items | all(.side_effects.external_mutation == false))
      and .side_effects.external_mutation == false
    ' "$BASE_GAP_WORK_QUEUE_PATH" >/dev/null
}

write_base_gap_backend_handoff() {
  base_gap_backend_handoff_json="$(
    jq -n \
      --arg product "Hepta Native" \
      --arg output_dir "$OUT_DIR" \
      --arg drilldown_path "$BASE_GAP_DRILLDOWN_PATH" \
      --arg work_queue_path "$BASE_GAP_WORK_QUEUE_PATH" \
      --argjson drilldown "$base_gap_drilldown_json" \
      --argjson work_queue "$base_gap_work_queue_json" \
      '
      def contract_groups_for($id): ({
        "message_search":[
          "Matrix search request/result/error/retry and loaded result-action handoffs (server query, From sender filter, Media URL filter, loaded-scope Filter/Date/Pins, and loaded Jump/Copy/Source/Thread/Sender live in hepta-ui native)",
          "remote result page and cursor identity (next_batch live in hepta-ui native)",
          "Matrix /search event_context before/after preview parsing and source-only FetchEventSource fallback (server context preview and current-room source refetch live in hepta-ui native)",
          "remote date index, pinned fetch, cross-room scope, and sort contract",
          "remote date/pins/scope/full-result result taxonomy packet",
          "stale-query and idempotency guard"
        ],
        "file_upload_send":[
          "SDK queue item identity, local echo mapping, and cached failed-handoff retry (single-file review SendAttachment and confirmed Retry live in hepta-ui native)",
          "upload progress bytes/percent exposed on timeline local echo (MediaUpload progress live)",
          "timeline local echo cancel via SendHandle::abort live; accepted queue pause/resume/retry/reorder/remove result",
          "delivery receipt and failed-state taxonomy",
          "idempotency and stale SendHandle guard",
          "accepted queue/progress/result taxonomy packet"
        ],
        "media_download_playback":[
          "FetchMedia cache read result (MediaCache::try_get_media_or_fetch live in hepta-ui native)",
          "SaveMedia/download result, row-scoped retry, opener status, and cached Open folder/Replay stale validation (SDK media cache save + confirmed SaveMedia Retry + system opener + stale cache eviction live in hepta-ui native)",
          "inline playback/decrypt/decode progress (inline/decrypt still blocked)",
          "codec/transcode/caption fallback result",
          "queue retry/resume/cancel/background persistence",
          "decrypt/decode/opener/queue result taxonomy packet",
          "encrypted-media error taxonomy"
        ],
        "notifications":[
          "room notification mode request/result/error/retry (All/Mentions/Mute SetRoomNotificationMode live in hepta-ui native)",
          "keyword Add/Remove mutation result/error/retry (NotificationSettings add_keyword/remove_keyword live in hepta-ui native)",
          "timed mute account-data contract",
          "global preference and pusher contract",
          "pusher/device write-side sound/badge contract (pusher capability read live in hepta-ui native)",
          "source-hash and stale-mode guard"
        ],
        "room_settings":[
          "loaded room identity/power/member refresh result (GetRoomPowerLevels + GetRoomMembers server-backed live in hepta-ui native)",
          "m.room.name/topic/canonical alias/avatar/history visibility/join-rule/tombstone mutation result/error/retry (SetRoomName/SetRoomTopic/SetRoomCanonicalAlias/UploadRoomAvatar/RemoveRoomAvatar/SetRoomHistoryVisibility/SetRoomJoinRule/SetRoomTombstone confirmed write and failed-state Retry live in hepta-ui native)",
          "power-level mutation result",
          "member moderation result and permission denial",
          "source-hash, retry, and stale-room guard"
        ],
        "matrix_link_resolution":[
          "compact room preview request/result/error/retry (PreviewMatrixLinkTarget live in hepta-ui native)",
          "current-room missing-event pagination result (BackwardsPaginateUntilEvent/PaginateTimeline live in hepta-ui native)",
          "room/alias/event/via route result",
          "server preview and non-current-room event context result",
          "confirmed browser handoff outcome plus room-or-alias JoinRoomByIdOrAlias, Knock result, and current-room user InviteUser result live",
          "source-only event source fetch result plus remaining full event-context failure taxonomy",
          "route/event-context result taxonomy packet",
          "source-hash and stale-target guard"
        ],
        "message_report_send":[
          "ReportContent request/result/error/retry (Room::report_content live in hepta-ui native)",
          "reported event source-only read fallback (MatrixRequest::FetchEventSource live in hepta-ui native)",
          "moderation queue persistence result",
          "policy lookup and reviewer assignment result",
          "evidence/source retention contract",
          "appeal/enforcement workflow result",
          "report retry/cancel/error taxonomy",
          "workflow result taxonomy packet"
        ],
        "message_edit_history":[
          "paginated m.replace relations request/result/error/retry to Room::relations next_batch exhaustion (FetchEditHistory live in hepta-ui native)",
          "full edit-history modal request/result",
          "loaded side-by-side preview/full-body diff snapshot (live in hepta-ui native) and server-backed full-history full-body diff payload",
          "replacement event context/source result",
          "remote full-history/source reconciliation result taxonomy packet",
          "stale-target, retry, and source-hash guard"
        ],
        "mention_picker_send":[
          "rich picker and richer directory-result UI beyond bounded user-id token promotion",
          "duplicate-name disambiguation result",
          "local hover-card snapshot (live in hepta-ui native) plus remote hover-card/profile adapter, source/tray/pill draft contract",
          "SendMessage/add_mentions plus attachment-caption AttachmentConfig.mentions result (both live in hepta-ui native)",
          "rich attachment editor plus edit/reply mention payload scopes",
          "remote hover/profile/disambiguation/edit-reply result taxonomy packet",
          "stale-token, source-hash, and idempotency guard"
        ],
        "voice_message_send":[
          "microphone permission and privacy entitlement result",
          "recorder/audio session and capture file lifecycle",
          "waveform/timer/codec/transcription result",
          "review playback/drop and mobile picker result",
          "desktop audio SendAttachment/failed-handoff Retry result (live in hepta-ui native) and stale-capture guard",
          "permission/capture/upload result taxonomy packet"
        ],
        "account_avatar_upload":[
          "source identity and desktop/mobile picker result",
          "cropper crop-box/aspect/rotate/zoom result",
          "camera/photo-library permission and capture result",
          "persistent thumbnail artifact, editor transform result, and mobile capture result",
          "UploadAvatar request/result/error/retry, SDK set_avatar_url(Some), direct SetAvatar(Some), and SetAvatar(None) result (confirmed upload/set, direct MXC set, failed-state Retry, and delete live in hepta-ui native)",
          "source/cropper/camera/editor artifact result taxonomy packet"
        ],
        "account_management":[
          "current device read/refresh result (GetOwnDevice live in hepta-ui native)",
          "all-device directory read result (GetDevices live in hepta-ui native)",
          "profile display-name result/retry (SetDisplayName live confirmed resubmit in hepta-ui native)",
          "current-device rename result (RenameDevice live confirmed in hepta-ui native)",
          "dedicated account-management portal route result (Browser/Portal homeserver opener live in hepta-ui native)",
          "password/SSO/revoke/trust/delete result taxonomy packet (local blocked UI evidence)",
          "password/SSO action result",
          "cross-session revoke/trust result",
          "device delete/trust and account/profile mutations beyond display name/current-device rename"
        ]
      }[$id]);
      def handoff_status_for($id):
        if ($id == "message_search" or $id == "file_upload_send" or $id == "media_download_playback" or $id == "notifications" or $id == "room_settings" or $id == "matrix_link_resolution" or $id == "message_report_send" or $id == "message_edit_history" or $id == "mention_picker_send" or $id == "voice_message_send" or $id == "account_avatar_upload" or $id == "account_management") then
          "partial_live_backend_contract_remaining"
        else
          "ready_for_backend_contract"
        end;
      def live_wiring_for($id):
        if ($id == "message_search") then
          "matrix_server_search_v3_search_next_batch_retry_context_pagination_sender_media_url_filter_loaded_scope_filters_loaded_result_actions_server_result_context_preview_source_refetch_live;remote_date_pins_scope_full_result_blocked"
        elif ($id == "file_upload_send") then
          "matrix_sdk_send_attachment_queue_live;failed_handoff_retry_sendattachment_live;timeline_progress_sendhandle_cancel_result_live;cross_platform_queue_controls_blocked"
        elif ($id == "media_download_playback") then
          "matrix_sdk_fetchmedia_save_media_retry_opener_openfolder_replay_live;inline_decrypt_queue_controls_blocked"
        elif ($id == "notifications") then
          "matrix_room_notification_mode_keyword_mutation_retry_keyword_list_default_mode_read_write_pusher_status_live;timed_pusher_sound_raw_rules_blocked"
        elif ($id == "room_settings") then
          "matrix_room_settings_power_member_server_refresh_name_topic_alias_avatar_history_joinrule_tombstone_retry_live;power_member_blocked"
        elif ($id == "matrix_link_resolution") then
          "matrix_link_compact_preview_retry_server_context_refresh_current_room_event_pagination_source_fetch_browser_opener_room_or_alias_join_knock_current_room_user_invite_live;event_context_route_adapter_blocked"
        elif ($id == "message_report_send") then
          "matrix_report_content_result_retry_loaded_source_fetch_modal_live;moderation_workflow_blocked"
        elif ($id == "message_edit_history") then
          "matrix_edit_history_paginated_relations_retry_local_full_snapshot_modal_loaded_original_replacement_source_side_by_side_preview_full_body_diff_live;remote_full_history_result_adapter_context_source_reconciliation_server_backed_full_body_diff_blocked"
        elif ($id == "mention_picker_send") then
          "matrix_sendmessage_attachment_caption_mentions_pill_tray_user_directory_search_result_promotion_hover_card_snapshot_live;rich_disambiguation_remote_hover_edit_payload_scopes_blocked"
        elif ($id == "voice_message_send") then
          "matrix_sendattachment_voice_audio_file_retry_review_opener_dropcleanup_selected_audio_waveform_codec_live;recorder_capture_upload_blocked"
        elif ($id == "account_avatar_upload") then
          "matrix_uploadavatar_setavatar_some_retry_setavatar_none_direct_mxc_setavatar_thumbnail_full_pixel_decode_live;source_cropper_camera_editor_thumbnail_artifact_blocked"
        elif ($id == "account_management") then
          "matrix_getowndevice_getdevices_retry_setdisplayname_resubmit_current_device_renamedevice_browser_portal_homeserver_opener_live;password_sso_revoke_trust_cross_session_device_mutations_blocked"
        else
          "blocked_until_backend_contract"
        end;
      {
        product:$product,
        output_dir:$output_dir,
        schema_version:1,
        native_base_gap_backend_handoff_ready:true,
        source_drilldown_path:$drilldown_path,
        source_drilldown_schema:$drilldown.schema_version,
        source_work_queue_path:$work_queue_path,
        source_work_queue_schema:$work_queue.schema_version,
        handoff_count:($work_queue.items | length),
        coverage:"12/12",
        ui_lane_state:"complete",
        next_owner_lane:"backend_contract",
        side_effect_profile:"ui-local-readiness-only",
        items:(
          $work_queue.items
          | map({
              id:.id,
              gap_id:.gap_id,
              priority:.priority,
              status:handoff_status_for(.id),
              ui_lane_state:.ui_lane_state,
              next_owner_lane:.next_owner_lane,
              current_ui_evidence:.current_ui_evidence,
              backend_contract_next_slice:.backend_contract_next_slice,
              required_backend_contracts:contract_groups_for(.id),
              acceptance_state:.acceptance_state + {
                ui_contract:"ready",
                backend_contract:"required",
                live_wiring:live_wiring_for(.id)
              },
              promotion_blocker:.promotion_blocker,
              verification_handoff:[
                "native-base-gap-drilldown.json acceptance criteria",
                "native-base-gap-work-queue.json ui_contract_ready items",
                "typed packet/contract markers in hepta_telegram_base_contract.rs",
                "scripts/hepta-ui-product-readiness-gate.sh combined artifact"
              ],
              side_effects:.side_effects
            })
          | sort_by(.priority)
        ),
        side_effects:$drilldown.side_effects
      }'
  )"

  printf '%s\n' "$base_gap_backend_handoff_json" >"$BASE_GAP_BACKEND_HANDOFF_PATH"

  jq -e \
    --arg drilldown_path "$BASE_GAP_DRILLDOWN_PATH" \
    --arg work_queue_path "$BASE_GAP_WORK_QUEUE_PATH" \
    '
      .schema_version == 1
      and .native_base_gap_backend_handoff_ready == true
      and .source_drilldown_path == $drilldown_path
      and .source_drilldown_schema == 2
      and .source_work_queue_path == $work_queue_path
      and .source_work_queue_schema == 2
      and .handoff_count == 12
      and .coverage == "12/12"
      and .ui_lane_state == "complete"
      and .next_owner_lane == "backend_contract"
      and .side_effect_profile == "ui-local-readiness-only"
      and (.items | length) == 12
      and ([.items[].priority] | sort) == [range(1;13)]
      and (.items | all(.status == "partial_live_backend_contract_remaining"))
      and (.items | map(select(.id == "message_search" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.items | map(select(.id == "file_upload_send" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.items | map(select(.id == "media_download_playback" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.items | map(select(.id == "notifications" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.items | map(select(.id == "room_settings" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.items | map(select(.id == "matrix_link_resolution" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.items | map(select(.id == "message_report_send" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.items | map(select(.id == "message_edit_history" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.items | map(select(.id == "mention_picker_send" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.items | map(select(.id == "voice_message_send" and .status == "partial_live_backend_contract_remaining")) | length) == 1
