run_backend_contract_gates() {
  local risk_plan_path="$BACKEND_CONTRACT_GATES_DIR/risk-plan.json"
  local notifications_path="$BACKEND_CONTRACT_GATES_DIR/notifications.json"
  local room_settings_path="$BACKEND_CONTRACT_GATES_DIR/room-settings.json"
  local message_report_path="$BACKEND_CONTRACT_GATES_DIR/message-report.json"
  local account_management_path="$BACKEND_CONTRACT_GATES_DIR/account-management.json"
  local queue_media_path="$BACKEND_CONTRACT_GATES_DIR/queue-media-permission.json"
  local remote_result_path="$BACKEND_CONTRACT_GATES_DIR/remote-result-rich-ux.json"

  HEPTA_NATIVE_UI_BACKEND_CONTRACT_RISK_PLAN_ALLOW_IN_PROGRESS=1 HEPTA_UI_PRODUCT_READINESS_DIR="$OUT_DIR" ./scripts/hepta-native-ui-backend-contract-risk-plan-gate.sh >"$risk_plan_path"
  HEPTA_UI_PRODUCT_READINESS_DIR="$OUT_DIR" ./scripts/hepta-native-notifications-backend-contract-gate.sh >"$notifications_path"
  HEPTA_UI_PRODUCT_READINESS_DIR="$OUT_DIR" ./scripts/hepta-native-room-settings-backend-contract-gate.sh >"$room_settings_path"
  HEPTA_UI_PRODUCT_READINESS_DIR="$OUT_DIR" ./scripts/hepta-native-message-report-backend-contract-gate.sh >"$message_report_path"
  HEPTA_UI_PRODUCT_READINESS_DIR="$OUT_DIR" ./scripts/hepta-native-account-management-backend-contract-gate.sh >"$account_management_path"
  HEPTA_UI_PRODUCT_READINESS_DIR="$OUT_DIR" ./scripts/hepta-native-queue-media-permission-contract-gate.sh >"$queue_media_path"
  HEPTA_UI_PRODUCT_READINESS_DIR="$OUT_DIR" ./scripts/hepta-native-remote-result-rich-ux-contract-gate.sh >"$remote_result_path"

  backend_contract_gates_json="$(
    jq -s \
      --arg output_dir "$OUT_DIR" \
      --arg report_path "$BACKEND_CONTRACT_GATES_REPORT_PATH" \
      --arg risk_plan_path "$risk_plan_path" \
      --arg notifications_path "$notifications_path" \
      --arg room_settings_path "$room_settings_path" \
      --arg message_report_path "$message_report_path" \
      --arg account_management_path "$account_management_path" \
      --arg queue_media_path "$queue_media_path" \
      --arg remote_result_path "$remote_result_path" \
      '{
        product:"Hepta Native",
        gate:"backend_contract_waves",
        status:"ready",
        output_dir:$output_dir,
        report_path:$report_path,
        backend_contract_waves_ready:true,
        risk_plan:.[0],
        waves:[.[1], .[2], .[3], .[4], .[5], .[6]],
        gate_reports:{
          risk_plan:$risk_plan_path,
          notifications:$notifications_path,
          room_settings:$room_settings_path,
          message_report:$message_report_path,
          account_management:$account_management_path,
          queue_media_permission:$queue_media_path,
          remote_result_rich_ux:$remote_result_path
        },
        verified_gap_count:12,
        covered_gap_ids:[
          "message_search",
          "file_upload_send",
          "media_download_playback",
          "notifications",
          "room_settings",
          "matrix_link_resolution",
          "message_report_send",
          "message_edit_history",
          "mention_picker_send",
          "voice_message_send",
          "account_avatar_upload",
          "account_management"
        ],
        side_effects:{
          matrix_login:false,
          gateway_call:false,
          provider_invoked:false,
          channel_delivery:false,
          external_mutation:false
        }
      }' \
      "$risk_plan_path" \
      "$notifications_path" \
      "$room_settings_path" \
      "$message_report_path" \
      "$account_management_path" \
      "$queue_media_path" \
      "$remote_result_path"
  )"

  printf '%s\n' "$backend_contract_gates_json" >"$BACKEND_CONTRACT_GATES_REPORT_PATH"

  jq -e '
    .backend_contract_waves_ready == true
    and .status == "ready"
    and .verified_gap_count == 12
    and (.covered_gap_ids | length) == 12
    and .risk_plan.status == "ready"
    and .risk_plan.verified_items == 12
    and (.waves | length) == 6
    and (.waves | all(.status == "ready"))
    and (.waves | map(select(.gate == "notifications_backend_contract")) | length) == 1
    and (.waves | map(select(.gate == "room_settings_backend_contract")) | length) == 1
    and (.waves | map(select(.gate == "message_report_backend_contract")) | length) == 1
    and (.waves | map(select(.gate == "account_management_backend_contract")) | length) == 1
    and (.waves | map(select(.gate == "queue_media_permission_backend_contract")) | length) == 1
    and (.waves | map(select(.gate == "remote_result_rich_ux_backend_contract")) | length) == 1
    and (.waves | all(.side_effects.external_mutation == false))
    and .risk_plan.side_effects.external_mutation == false
    and .side_effects.external_mutation == false
  ' "$BACKEND_CONTRACT_GATES_REPORT_PATH" >/dev/null
}

