          tsp_wallet_destructive_import:$tsp_wallet_path,
          spaces_room_membership_edge:$spaces_room_path,
          edit_poll_detail:$edit_poll_path,
          non_base_edge_risk_plan:$risk_plan_path
        },
        verified_edge_count:4,
        covered_edge_ids:[
          "location_continuous_device_updates_local_controls",
          "tsp_wallet_destructive_import_actions",
          "spaces_room_membership_edges",
          "edit_poll_detail_edges"
        ],
        readiness_dependency:"pre_readiness_source_marker_gate",
        side_effects:{
          matrix_login:false,
          gateway_call:false,
          provider_invoked:false,
