      "$risk_plan_path"
  )"

  printf '%s\n' "$non_base_edge_gates_json" >"$NON_BASE_EDGE_GATES_REPORT_PATH"

  jq -e '
    .non_base_edge_gates_ready == true
    and .status == "ready"
    and .verified_edge_count == 4
    and (.covered_edge_ids | length) == 4
    and (.gates | length) == 4
    and (.gates | all(.status == "ready"))
    and (.gates | map(select(.gate == "tsp_wallet_destructive_import_backend_contract")) | length) == 1
    and (.gates | map(select(.gate == "spaces_room_membership_edge_backend_contract")) | length) == 1
    and (.gates | map(select(.gate == "edit_poll_detail_backend_contract")) | length) == 1
    and (.gates | map(select(.gate == "non_base_edge_risk_plan")) | length) == 1
    and (.gates | all(.side_effects.external_mutation == false))
    and .side_effects.external_mutation == false
  ' "$NON_BASE_EDGE_GATES_REPORT_PATH" >/dev/null
}

