run_backend_dispatch_packet_gate() {
  if [[ "$REUSE_BACKEND_DISPATCH_PACKET" == "1" ]]; then
    {
      printf 'Reusing existing UI backend dispatch packet gate artifacts\n'
      printf 'report=%s\n' "$BACKEND_DISPATCH_PACKET_REPORT_PATH"
      printf 'packet_dir=%s\n' "$BACKEND_DISPATCH_PACKET_DIR"
    } >"$BACKEND_DISPATCH_PACKET_LOG"
  else
    run_logged_gate \
      "UI backend dispatch packet gate" \
      "$BACKEND_DISPATCH_PACKET_LOG" \
      env \
        HEPTA_UI_PRODUCT_READINESS_DIR="$OUT_DIR" \
        HEPTA_UI_BACKEND_DISPATCH_PACKET_REPORT_PATH="$BACKEND_DISPATCH_PACKET_REPORT_PATH" \
        HEPTA_UI_BACKEND_DISPATCH_PACKET_DIR="$BACKEND_DISPATCH_PACKET_DIR" \
        ./scripts/hepta-ui-backend-dispatch-packet-gate.sh
  fi

  if [[ ! -s "$BACKEND_DISPATCH_PACKET_REPORT_PATH" ]]; then
    echo "UI backend dispatch packet report missing: ${BACKEND_DISPATCH_PACKET_REPORT_PATH}" >&2
    exit 1
  fi

  if [[ ! -s "$BACKEND_DISPATCH_PACKET_ARCHIVE_PATH" ]]; then
    echo "UI backend dispatch packet archive missing: ${BACKEND_DISPATCH_PACKET_ARCHIVE_PATH}" >&2
    exit 1
  fi

  if [[ ! -s "$BACKEND_DISPATCH_PACKET_MANIFEST_PATH" ]]; then
    echo "UI backend dispatch packet manifest missing: ${BACKEND_DISPATCH_PACKET_MANIFEST_PATH}" >&2
    exit 1
  fi

  if [[ ! -s "$BACKEND_DISPATCH_PACKET_MARKDOWN_PATH" ]]; then
    echo "UI backend dispatch packet markdown missing: ${BACKEND_DISPATCH_PACKET_MARKDOWN_PATH}" >&2
    exit 1
  fi

  local local_backend_dispatch_packet_report_path="$OUT_DIR/ui-backend-dispatch-packet-gate.json"
  if [[ "$REUSE_BACKEND_DISPATCH_PACKET" == "1" && -n "${HEPTA_UI_BACKEND_AGENT_PROBE_PATH:-}" ]]; then
    if [[ ! -s "$HEPTA_UI_BACKEND_AGENT_PROBE_PATH" ]]; then
      echo "backend agent probe missing: ${HEPTA_UI_BACKEND_AGENT_PROBE_PATH}" >&2
      exit 1
    fi
    jq empty "$HEPTA_UI_BACKEND_AGENT_PROBE_PATH" >/dev/null
    jq \
      --arg backend_agent_probe_path "$HEPTA_UI_BACKEND_AGENT_PROBE_PATH" \
      --slurpfile backend_agent_probe_file "$HEPTA_UI_BACKEND_AGENT_PROBE_PATH" \
      '
      ($backend_agent_probe_file[0]) as $agent_probe
      | def controlled_backend_agent_available:
          (
            ($agent_probe.status // "") == "ok"
            and (($agent_probe.sessionKey // "") | test("^agent:hepta-backend:"))
          )
          or
          (
            ($agent_probe.reply // "") == "HEPTA_UI_SESSIONS_SEND_PROBE_OK"
            and (($agent_probe.sessionKey // "") | test("^agent:hepta-backend:"))
          );
        . + {
          backend_agent_probe:{
            evidence_path:$backend_agent_probe_path,
            status:($agent_probe.status // null),
            reply:($agent_probe.reply // null),
            session_key:($agent_probe.sessionKey // null),
            controlled_sessions_send_ready:controlled_backend_agent_available
          },
          dispatch_guardrail:(.dispatch_guardrail + {
            backend_agent_available:controlled_backend_agent_available
          })
        }
      ' "$BACKEND_DISPATCH_PACKET_REPORT_PATH" >"$local_backend_dispatch_packet_report_path"
    BACKEND_DISPATCH_PACKET_REPORT_PATH="$local_backend_dispatch_packet_report_path"
  elif [[ "$BACKEND_DISPATCH_PACKET_REPORT_PATH" != "$local_backend_dispatch_packet_report_path" ]]; then
    cp "$BACKEND_DISPATCH_PACKET_REPORT_PATH" "$local_backend_dispatch_packet_report_path"
    BACKEND_DISPATCH_PACKET_REPORT_PATH="$local_backend_dispatch_packet_report_path"
  fi

  backend_dispatch_packet_json="$(<"$BACKEND_DISPATCH_PACKET_REPORT_PATH")"

  jq -e '
    .status == "ready"
    and .backend_dispatch_packet_gate_ready == true
    and .packet_kind == "local_backend_dispatch_packet"
    and .packet_version == 1
    and .selected_packet_ids == ["message_search","file_upload_send","media_download_playback","notifications","room_settings"]
    and .packet_item_count == 5
    and .packet_ready_count == 5
    and .payload_file_count == 8
    and .extracted_file_count == 8
    and .all_extracted_files_sha256_match == true
    and (.archive_sha256 | test("^[0-9a-f]{64}$"))
    and .archive_bytes > 0
    and (.manifest_sha256 | test("^[0-9a-f]{64}$"))
    and .manifest_bytes > 0
    and (.packet_markdown_sha256 | test("^[0-9a-f]{64}$"))
    and .packet_markdown_bytes > 0
    and .backend_lane_target.target_repo == "/Users/qianqi/.openclaw/workspace/Hepta"
    and .backend_lane_target.owner_lane == "backend_contract"
    and (.hepta_ui_after_backend.required_refresh_commands | length) == 2
    and (.backend_agent_probe.controlled_sessions_send_ready | type) == "boolean"
    and .dispatch_guardrail.local_dispatch_packet_ready == true
    and .dispatch_guardrail.external_dispatch_performed == false
    and (.dispatch_guardrail.backend_agent_available | type) == "boolean"
    and .dispatch_guardrail.backend_adapter_promoted == false
    and .dispatch_guardrail.live_runtime_mutation == false
    and .dispatch_guardrail.live_product_claim_ready == false
    and .claim_boundary.local_backend_dispatch_packet_ready == true
    and .claim_boundary.local_backend_handoff_export_ready == true
    and .claim_boundary.local_backend_contract_acceptance_ready == true
    and .claim_boundary.backend_adapter_promoted == false
    and .claim_boundary.readback_evidence_recorded == false
    and .claim_boundary.live_runtime_mutation == false
    and .claim_boundary.live_product_claim_ready == false
    and .claim_boundary.public_distribution_claim_ready == false
    and .claim_boundary.release_claim_ready == false
    and .claim_boundary.external_actions_allowed == false
    and .side_effects.local_archive_written == true
    and .side_effects.local_extract_verification == true
    and .side_effects.backend_adapter_promoted == false
    and .side_effects.live_runtime_mutation == false
    and .side_effects.external_mutation == false
  ' "$BACKEND_DISPATCH_PACKET_REPORT_PATH" >/dev/null
}

prepare_backend_delivery_receipt_input() {
