        post_r228_risk_future_plan_release_claim_ready:$post_r228_risk_future_plan.claim_boundary.release_claim_ready,
        post_r228_risk_future_plan_external_actions_allowed:$post_r228_risk_future_plan.claim_boundary.external_actions_allowed,
        post_r228_risk_future_plan_source_control_sha256:$post_r228_risk_future_plan.source_report_sha256.control_browser,
        post_r228_risk_future_plan_source_old_control_sha256:$post_r228_risk_future_plan.source_report_sha256.old_control_browser,
        ui_root_report_replay_gate_ready:$root_report_replay.root_report_replay_gate_ready,
        ui_root_report_replay:$root_report_replay,
        local_root_report_replay_ready:$root_report_replay.claim_boundary.local_root_report_replay_ready,
        root_report_replay_count:$root_report_replay.root_report_count,
        local_fixture_demo_ready:$plan_boundary.claim_boundary.local_fixture_demo_ready,
        r33_minimum_hard_demo_ready:$plan_boundary.claim_boundary.r33_minimum_hard_demo_ready,
        live_product_claim_ready:$plan_boundary.live_product_claim.ready,
        public_distribution_claim_ready:$plan_boundary.claim_boundary.public_distribution_claim_ready,
        release_claim_ready:$plan_boundary.release_claim.ready,
        backend_contract_remaining_count:$plan_boundary.live_product_claim.remaining_backend_contract_count,
        backend_contract_next_owner_lane:$plan_boundary.live_product_claim.next_owner_lane,
	        release_claim_blockers:release_plan_blockers,
	        next_plan:release_signing_aware_current_plan,
	        release_signing_aware_next_plan_ready:true,
	        next_unblock_sequence:release_signing_aware_next_unblock_sequence,
	        release_signing_aware_next_unblock_sequence_ready:true,
        screenshot_count:{
          control_ui:$control_screenshot_count,
          native:$native_screenshot_count,
          key:$key_screenshot_count,
          native_selected_row_variants:$selected_row_variant_count,
          native_selected_row_unique:$native_fixture.selected_row_unique_count,
          native_route_variants_unique:$native_fixture.route_variant_unique_count,
          native_mobile_route_variants_unique:$native_fixture.mobile_route_variant_unique_count,
          native_true_window:(($native_window.screenshots // []) | length),
          native_true_window_route:(($native_window_route.screenshots // []) | length),
          native_true_window_secondary:(($native_window_secondary.screenshots // []) | length),
          native_true_window_secondary_mobile:(($native_window_secondary_mobile.screenshots // []) | length)
        },
        output_dirs:{
          control_ui:$control_output_dir,
          native:$native_output_dir,
          native_window:$native_window_output_dir,
          native_window_route:$native_window_route_output_dir,
          native_window_secondary:$native_window_secondary_output_dir,
          native_window_secondary_mobile:$native_window_secondary_mobile_output_dir
        },
        side_effects:{
          local_loopback_server_spawned:$native_packaging.runner.local_loopback_spawned,
          matrix_login:false,
          gateway_call:false,
          provider_invoked:false,
          channel_delivery:false,
          external_mutation:false
        }
      }'
  )"
  printf '%s\n' "$artifact_summary_json" >"$ARTIFACT_SUMMARY_PATH"
}

validate_written_artifacts() {
  jq -e \
    --argjson min_screenshot_bytes "$MIN_SCREENSHOT_BYTES" \
    '
      .screenshot_manifest_ready == true
      and .screenshot_count.control_ui >= 4
      and .screenshot_count.native >= 40
      and .screenshot_count.total >= (.screenshot_count.control_ui + .screenshot_count.native)
      and .key_screenshot_count >= 24
      and (.key_screenshots | length) == .key_screenshot_count
      and (
        (.native.true_window_smoke_enabled != true)
        or (
          .screenshot_count.native_true_window == 2
          and .native.true_window_smoke_ready == true
          and .native.true_window_screenshot_count == 2
          and (.native.true_window_screenshots | length) == 2
        )
      )
      and (
        (.native.true_window_route_smoke_enabled != true)
        or (
          .screenshot_count.native_true_window_route == 4
          and .native.true_window_route_smoke_ready == true
          and .native.true_window_route_screenshot_count == 4
          and .native.true_window_route_content_probe_ready == true
          and (.native.true_window_route_screenshots | length) == 4
          and (.native.true_window_route_screenshots | all(.visual_probe.route_content_ready == true))
        )
      )
      and (.native.selected_row_variant_count >= 18)
      and .native.selected_row_unique_count == .native.selected_row_variant_count
      and .native.route_variant_unique_count == 4
      and .native.mobile_route_variant_unique_count == 4
      and .native.tempered_glass_visual_contract_ready == true
      and .native.tempered_glass_visual_contract.status == "ready"
      and .native.readability_contrast_clip_ready == true
      and .native.secondary_product_surfaces_ready == true
      and .native.secondary_product_surfaces.status == "ready"
      and .native.secondary_product_surfaces.surface_count == 5
      and .native.secondary_product_surfaces.viewport_count == 3
      and .native.secondary_product_surfaces.case_count == 15
      and .native.secondary_product_surfaces.actions_in_surface == true
      and .native.secondary_product_surfaces.text_clipping_failure_count == 0
      and .native.secondary_product_surfaces.content_edge_failure_count == 0
      and .native.secondary_product_surfaces.visible_audit_failure_count == 0
      and (
        .key_screenshots
        | all(
          .bytes >= $min_screenshot_bytes
          and (.sha256 | test("^[0-9a-f]{64}$"))
          and (.path | length > 0)
        )
      )
    ' "$MANIFEST_PATH" >/dev/null

  jq -e \
    --argjson min_screenshot_bytes "$MIN_SCREENSHOT_BYTES" \
    --slurpfile blocker_closure "$BLOCKER_CLOSURE_REPORT_PATH" \
    --slurpfile backend_delivery_audit "$BACKEND_DELIVERY_AUDIT_REPORT_PATH" \
