    and (.native_base_gap_backend_handoff.items | map(select(.id == "voice_message_send" and .status == "partial_live_backend_contract_remaining")) | length) == 1
    and (.native_base_gap_backend_handoff.items | map(select(.id == "account_avatar_upload" and .status == "partial_live_backend_contract_remaining")) | length) == 1
    and (.native_base_gap_backend_handoff.items | map(select(.id == "account_management" and .status == "partial_live_backend_contract_remaining")) | length) == 1
    and (.native_base_gap_backend_handoff.items | all(.ui_lane_state == "complete"))
    and (.native_base_gap_backend_handoff.items | all(.next_owner_lane == "backend_contract"))
    and (.native_base_gap_backend_handoff.items | all((.required_backend_contracts | length) >= 5))
    and (.native_base_gap_backend_handoff.items | all(.side_effects.external_mutation == false))
    and .native_packaging.local_packaging_gate_ready == true
    and .native_packaging.local_unsigned_app_bundle_probe_ready == true
    and .native_packaging.local_unsigned_app_bundle.ready == true
    and .native_packaging.local_unsigned_app_bundle.bundle_identifier == "ai.hepta.nativeapp"
    and .native_packaging.local_unsigned_app_bundle.bundle_executable == "hepta-native"
    and .native_packaging.local_unsigned_app_bundle.distribution_signed == false
    and .native_packaging.local_unsigned_app_bundle.public_distribution_artifact_written == false
    and .native_distribution_preflight_gate_ready == true
    and .native_distribution_preflight.distribution_preflight_gate_ready == true
    and .native_distribution_preflight.distribution_static_contract_ready == true
    and .native_distribution_preflight.unsigned_app_bundle_probe.ready == true
    and .native_distribution_preflight.public_distribution_ready == false
    and .native_distribution_preflight.credential_values_read == false
    and .native_distribution_preflight.notary_submission_performed == false
    and .native_distribution_preflight.public_distribution_artifact_written == false
    and .native_packaging.missing_route_count == 0
    and .screenshot_count.control_ui >= 4
    and .screenshot_count.native >= 40
    and .screenshot_count.key >= 13
    and .screenshot_count.native_selected_row_variants >= 18
    and .side_effects.matrix_login == false
    and .side_effects.gateway_call == false
    and .side_effects.provider_invoked == false
    and .side_effects.channel_delivery == false
    and .side_effects.external_mutation == false
	    and (
	      (.native_window_smoke_enabled == false)
	      or (.native_window_smoke.status != "ready")
	      or (
	        .native_window_smoke_ready == true
        and .native_window_app_log_error_free == true
        and .native_window_screenshot_count == 2
        and (.native_window_screenshots | length) == 2
        and (
          .native_window_screenshots
          | all(
            .bytes >= $min_screenshot_bytes
            and (.sha256 | test("^[0-9a-f]{64}$"))
            and (.path | length > 0)
            and .visual_probe.ready == true
          )
	        )
	      )
	    )
	    and (
	      (.native_window_route_smoke_enabled == false)
	      or (.native_window_route_smoke.status != "ready")
	      or (
	        .native_window_route_smoke_ready == true
	        and .native_window_route_app_log_error_free == true
	        and .native_window_route_screenshot_count == 4
	        and .native_window_route_screenshot_unique_count == 4
	        and .native_window_route_screenshot_unique_ready == true
	        and .native_window_route_top_design_referee_ready == true
	        and .native_window_route_content_probe_ready == true
	        and (.native_window_route_screenshots | length) == 4
	        and (
	          .native_window_route_screenshots
	          | all(
	            .bytes >= $min_screenshot_bytes
	            and (.sha256 | test("^[0-9a-f]{64}$"))
	            and (.path | length > 0)
	            and .visual_probe.ready == true
	            and .visual_probe.route_content_ready == true
	          )
	        )
	      )
	    )
	    and (
	      (.native_window_secondary_smoke_enabled == false)
	      or (.native_window_secondary_smoke.status != "ready")
	      or (
	        .native_window_secondary_smoke_ready == true
	        and .native_window_secondary_app_log_error_free == true
	        and .native_window_secondary_screenshot_count == 5
	        and .native_window_secondary_screenshot_unique_count == 5
	        and .native_window_secondary_screenshot_unique_ready == true
	        and (.native_window_secondary_screenshots | length) == 5
	        and (
	          .native_window_secondary_screenshots
	          | all(
	            .bytes >= $min_screenshot_bytes
	            and (.sha256 | test("^[0-9a-f]{64}$"))
	            and (.path | length > 0)
	            and .visual_probe.ready == true
	          )
	        )
	      )
	    )
	    and (
	      (.native_window_secondary_mobile_smoke_enabled == false)
	      or (.native_window_secondary_mobile_smoke.status != "ready")
	      or (
	        .native_window_secondary_mobile_smoke_ready == true
	        and .native_window_secondary_mobile_app_log_error_free == true
	        and .native_window_secondary_mobile_content_probe_ready == true
	        and .native_window_secondary_mobile_content_visible_count >= 5
	        and .native_window_secondary_mobile_screenshot_count == 5
	        and .native_window_secondary_mobile_screenshot_unique_count == 5
	        and .native_window_secondary_mobile_screenshot_unique_ready == true
	        and (.native_window_secondary_mobile_screenshots | length) == 5
	        and (
	          .native_window_secondary_mobile_screenshots
	          | all(
	            .bytes >= $min_screenshot_bytes
	            and (.sha256 | test("^[0-9a-f]{64}$"))
	            and (.path | length > 0)
	            and .visual_probe.ready == true
	            and .visual_probe.mobile_secondary_content_ready == true
	          )
	        )
	      )
	    )
	  ' "$ARTIFACT_SUMMARY_PATH" >/dev/null
}

write_handoff_report() {
  local key_screenshots_json="$1"
  local handoff_release_claim_blockers
  local handoff_release_signing_blockers
  local handoff_release_next_unblock_sequence
  local handoff_release_artifact_input_mode
  local handoff_release_artifact_receipt_semantics
