  local handoff_release_artifact_source_public_upload

  handoff_release_claim_blockers="$(jq -r '.release_claim_blockers | join(",")' "$ARTIFACT_SUMMARY_PATH")"
  handoff_release_signing_blockers="$(jq -r '.release_signing_blockers | join(",")' "$ARTIFACT_SUMMARY_PATH")"
