	      def real_release_artifact_receipt_present:
	        ($release_artifact_intake.release_artifact_state.release_artifact_present // false) == true
	        and ($release_artifact_intake.release_artifact_state.release_artifact_valid // false) == true
	        and release_artifact_receipt_semantics == "local_signed_notarized_stapled_dmg_written_not_public_upload";
	      def simulated_or_supplied_artifact_blocked_from_release_claim:
	        ($release_artifact_intake.release_artifact_state.release_artifact_present // false) == true
