	          "waiting_for_artifact"
	        elif real_release_artifact_receipt_present then
	          "real_build_macos_dmg_receipt"
	        else
	          "local_simulated_or_supplied_artifact_receipt_not_release_claimable"
	        end;
	      def release_artifact_realness_blockers:
	        [
	          (if real_release_artifact_receipt_present then empty else "signed_notarized_stapled_artifact_missing" end),
	          (
	            if (
	              real_release_artifact_receipt_present
	              and ($release_artifact_intake.release_artifact_state.public_distribution_artifact_written // false) == true
	            ) then
	              empty
	            else
	              "public_distribution_artifact_not_written"
	            end
	          )
	        ];
	      def release_plan_blockers:
	        (($current_plan_refresh.current_plan[3].blockers // [])
	        + ($release_signing_capability.blockers // [])
	        + release_artifact_realness_blockers) | unique_preserve_order;
	      def release_signing_next_unblock_sequence:
	        if ($release_signing_capability.release_execution_prerequisites.release_signing_execution_prerequisites_ready // false) == true then
	          []
	        else
	          [
	            "provision_developer_id_identity_and_notary_profile",
	            "collect_real_signed_notarized_stapled_artifact_before_public_distribution"
	          ]
	        end;
	      def release_signing_aware_current_plan:
	        ($current_plan_refresh.current_plan // []) as $plan
	        | if ($plan | length) > 3 then
	            $plan
	            | .[3] += {
	                blockers:release_plan_blockers,
	                release_signing_execution_prerequisites_ready:($release_signing_capability.release_execution_prerequisites.release_signing_execution_prerequisites_ready // false),
