	                signed_notarized_stapled_artifact_present:real_release_artifact_receipt_present,
	                local_distribution_artifact_written:(
	                  real_release_artifact_receipt_present
	                  and ($release_artifact_intake.release_artifact_state.local_distribution_artifact_written // false) == true
	                ),
	                public_distribution_artifact_written:(
	                  real_release_artifact_receipt_present
	                  and ($release_artifact_intake.release_artifact_state.public_distribution_artifact_written // false) == true
	                ),
	                public_release_claim_blocked_by_signing_capability:(
	                  ($release_signing_capability.release_execution_prerequisites.release_signing_execution_prerequisites_ready // false) == false
	                )
	              }
	          else
	            $plan
	          end;
	      def release_signing_aware_next_unblock_sequence:
	        (
	          ($blocker_closure.next_unblock_sequence // [])
	          + release_signing_next_unblock_sequence
	          + (
	            if real_release_artifact_receipt_present then
