      and ([.native_base_gap_work_queue.items[].priority] | sort) == [range(1;13)]
      and (.native_base_gap_work_queue.items | all(.status == "ui_contract_ready"))
      and (.native_base_gap_work_queue.items | all(.ui_lane_state == "complete"))
      and (.native_base_gap_work_queue.items | all(.next_owner_lane == "backend_contract"))
      and (.native_base_gap_work_queue.items | all(.side_effects.external_mutation == false))
      and .native_base_gap_backend_handoff.schema_version == 1
      and .native_base_gap_backend_handoff.source_drilldown_schema == 2
      and .native_base_gap_backend_handoff.source_work_queue_schema == 2
      and ([.native_base_gap_backend_handoff.items[].priority] | sort) == [range(1;13)]
      and (.native_base_gap_backend_handoff.items | all(.status == "partial_live_backend_contract_remaining"))
      and (.native_base_gap_backend_handoff.items | map(select(.id == "message_search" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.native_base_gap_backend_handoff.items | map(select(.id == "file_upload_send" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.native_base_gap_backend_handoff.items | map(select(.id == "media_download_playback" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.native_base_gap_backend_handoff.items | map(select(.id == "notifications" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.native_base_gap_backend_handoff.items | map(select(.id == "room_settings" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.native_base_gap_backend_handoff.items | map(select(.id == "matrix_link_resolution" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.native_base_gap_backend_handoff.items | map(select(.id == "message_report_send" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.native_base_gap_backend_handoff.items | map(select(.id == "message_edit_history" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.native_base_gap_backend_handoff.items | map(select(.id == "mention_picker_send" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.native_base_gap_backend_handoff.items | map(select(.id == "voice_message_send" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.native_base_gap_backend_handoff.items | map(select(.id == "account_avatar_upload" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.native_base_gap_backend_handoff.items | map(select(.id == "account_management" and .status == "partial_live_backend_contract_remaining")) | length) == 1
      and (.native_base_gap_backend_handoff.items | all(.ui_lane_state == "complete"))
      and (.native_base_gap_backend_handoff.items | all(.next_owner_lane == "backend_contract"))
      and (.native_base_gap_backend_handoff.items | all((.required_backend_contracts | length) >= 5))
      and (.native_base_gap_backend_handoff.items | all(.side_effects.external_mutation == false))
      and .artifact_manifest.screenshot_manifest_ready == true
      and .native_packaging.local_packaging_gate_ready == true
      and .native_packaging.local_unsigned_app_bundle_probe_ready == true
      and .native_packaging.local_unsigned_app_bundle.ready == true
      and .native_packaging.local_unsigned_app_bundle.bundle_identifier == "ai.hepta.nativeapp"
      and .native_packaging.local_unsigned_app_bundle.distribution_signed == false
      and .native_packaging.local_unsigned_app_bundle.public_distribution_artifact_written == false
      and .native_distribution_preflight_gate_ready == true
      and .native_distribution_preflight.distribution_preflight_gate_ready == true
      and .native_distribution_preflight.distribution_static_contract_ready == true
      and .native_distribution_preflight.public_distribution_ready == false
      and .native_distribution_preflight.notary_submission_performed == false
      and .native_distribution_preflight.public_distribution_artifact_written == false
      and .ui_release_signing_capability_gate_ready == true
      and .ui_release_signing_capability.status == "ready"
      and .local_release_signing_capability_audit_ready == true
      and (.release_signing_execution_prerequisites_ready | type) == "boolean"
      and (.release_signing_keychain_identity_ready | type) == "boolean"
      and (.release_signing_notary_env_ready | type) == "boolean"
      and (.release_signing_notary_keychain_profile_ready | type) == "boolean"
      and (.release_signing_notary_credentials_ready | type) == "boolean"
      and (.ui_release_signing_capability.notary_credentials.optional_keychain_profile_keychain_lookup_performed | type) == "boolean"
      and (.ui_release_signing_capability.notary_credentials.optional_keychain_profile_keychain_item_found | type) == "boolean"
      and (.ui_release_signing_capability.notary_credentials.optional_keychain_profile_lookup_output_sha256 | test("^[0-9a-f]{64}$"))
      and .ui_release_signing_capability.notary_credentials.optional_keychain_profile_lookup_output_bytes > 0
      and .ui_release_signing_capability.notary_credentials.optional_keychain_profile_lookup_raw_output_persisted == false
      and .ui_release_signing_capability.side_effects.keychain_identity_lookup_raw_output_persisted == false
      and .ui_release_signing_capability.side_effects.notary_profile_keychain_lookup_raw_output_persisted == false
      and .ui_release_signing_capability.side_effects.credential_value_captured == false
      and .ui_release_signing_capability.side_effects.network_call_performed == false
      and .ui_release_signing_capability.side_effects.notary_submission_performed == false
      and .ui_release_signing_capability.side_effects.app_signed == false
      and .ui_release_signing_capability.side_effects.app_notarized == false
      and .ui_release_signing_capability.side_effects.app_stapled == false
      and .ui_release_signing_capability.side_effects.public_distribution_artifact_written == false
      and .ui_release_signing_capability.side_effects.external_mutation == false
      and .side_effects.external_mutation == false
    ' "$READINESS_REPORT_PATH" >/dev/null

  printf '%s\n' "$readiness_json"
}

